   double[] Oracle(double[] x,bool normal){var o=normal?new double[3]:ExpectedAxis.Take(3).ToArray();var k=ExpectedAxis.Skip(3).ToArray();var v=x.Zip(o,(a,b)=>a-b).ToArray();double radians=ExpectedAngle*Math.PI/180,c=Math.Cos(radians),t=Math.Sin(radians),d=v.Zip(k,(u,z)=>u*z).Sum();var cross=new[]{k[1]*v[2]-k[2]*v[1],k[2]*v[0]-k[0]*v[2],k[0]*v[1]-k[1]*v[0]};return Enumerable.Range(0,3).Select(i=>o[i]+c*v[i]+t*cross[i]+(1-c)*d*k[i]).ToArray();}
