  internal static int Run(){Need(File.Exists(Path.Combine(Program.Root,".surface-rotation-fixture")),"Isolated surface rotation marker required; never CAD.");int guards=0;foreach(object angle in new object[]{0,360,-720,1000001,2147483648L,1.5,"90"}){bool rejected=false;try{OwnedSurfaceRotation.Angle(angle);}catch(Exception){rejected=true;}Need(rejected,"Invalid angle accepted");guards++;}bool legacy=false;try{OwnedSurfaceRotation.Axis(new Dictionary<string,object>{{"angleDegrees",-30},{"nativeAxis",new[]{0.0,0,0,0,0,1}},{"measurementProfile",OwnedSurfaceRotation.Profile}});}catch(Exception){legacy=true;}Need(legacy,"Legacy Z90 profile accepted new angle");guards++;var rows=new List<object>();foreach(string fault in new[]{"control","control_oblique","return_zero","throw_after","wrong_position","wrong_normal","other_drift","area_drift"}){
