   string sha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",id+".json"),e);Need(Equals(OwnedTranslation.Execute(f.Root,Guid.NewGuid().ToString("N"),args,c,true,true)["state"],"owned_surface_rotation_rejected_before_change")&&c.Calls==1,"Rotation replay reached callback");DateTime stamp=DateTime.UtcNow;if(fault!="throw_after"){var j=NativeJournal.ForVerification(f.Root,id,(string)e["planSha256"]);if(stamp<=j.CommandReturnedUtc)stamp=j.CommandReturnedUtc.AddTicks(1);}var o=c.Observation();o["timestampUtc"]=stamp.ToString("o");var w=c.Windows();w["timestampUtc"]=stamp.AddTicks(1).ToString("o");w["state"]="documents_listed_verified";string inspect=Guid.NewGuid().ToString("N"),listing=Guid.NewGuid().ToString("N");var proof=new Dictionary<string,object>{{"executionRequestId",id},{"executionReceiptSha256",sha},{"inspectionRequestId",inspect},{"inspectionSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",inspect+".json"),o)},{"listingRequestId",listing},{"listingSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",listing+".json"),w)},{"windowNumber",1},{"modelId",9},{"expiresUtc",DateTime.UtcNow.AddSeconds(150).ToString("o")}};
