  }Directory.CreateDirectory(Path.Combine(Program.Root,"reports"));NativeJournal.Freeze(Path.Combine(Program.Root,"reports","surface-rotation-tests.json"),new{state="passed",rows,guards,cadConnectionAttempted=false});Console.WriteLine("PASS: "+(rows.Count+guards)+" surface rotation lifecycle/position/normal/fence controls; no CAD.");return rows.Count+guards;}
